errores.mal:
// El carrito vive en la memoria de UNA instancia
const carritos = {};
app.post('/carrito', (req, res) => {
  carritos[req.ip] = req.body;
});

errores.bien:
// El carrito se guarda en la base de datos
app.post('/carrito', autenticar, async (req, res) => {
  await carritos.guardar(req.usuario.id, req.body);
  res.sendStatus(204);
});

